const test = require("node:test");
const assert = require("node:assert");

const { newSubscribers } = require("./subscribers");

test("finds additions, keeps order and duplicates", () => {
  assert.deepStrictEqual(
    newSubscribers(["a@x.io", "b@x.io", "a@x.io", "c@x.io"], ["b@x.io"]),
    ["a@x.io", "a@x.io", "c@x.io"],
  );
});

test("empty edges", () => {
  assert.deepStrictEqual(newSubscribers([], ["a@x.io"]), []);
  assert.deepStrictEqual(newSubscribers(["a@x.io"], []), ["a@x.io"]);
});

test("performance on large lists", () => {
  const n = 30000;
  const previous = Array.from({ length: n }, (_, i) => `user${i}@example.com`);
  const current = Array.from({ length: n }, (_, i) => `user${i + n / 2}@example.com`);

  const start = process.hrtime.bigint();
  const got = newSubscribers(current, previous);
  const elapsed = Number(process.hrtime.bigint() - start) / 1e9;

  assert.strictEqual(got.length, n / 2);
  assert.strictEqual(got[0], `user${n}@example.com`);
  // calibrated: Array.includes per element is ~7s on fast native hardware
  // and slower in the sandbox; the Set version is ~0.01s
  assert.ok(
    elapsed < 2.5,
    `newSubscribers took ${elapsed.toFixed(2)}s for ${n}x${n}; expected a Set ` +
      `lookup, not previous.includes() inside the loop (O(n*m))`,
  );
});

