function newSubscribers(current, previous) {
  // Emails present in the current list but absent from the previous one,
  // in current-list order (duplicates in `current` preserved).
  const prev = new Set(previous);
  return [...new Set(current)].filter((email) => !prev.has(email));
}

module.exports = { newSubscribers };

